noncomputable def baseMat5 (B : BG) (ξ : Cyl) : Matrix (Fin 3) (Fin 3) ℝ :=
  !![qC B.h ξ ^ (2 * Aex B.h + 1/2) * qC B.h ξ ^ (-Aex B.h) * dR B.h (fun η => ubase B η 0) ξ, 0,
      qC B.h ξ ^ (2 * Aex B.h + 1/2) * qC B.h ξ ^ (-Aex B.h) * dZ (fun η => ubase B η 0) ξ;
     0, qC B.h ξ ^ (2 * Aex B.h + 1/2) * qC B.h ξ ^ (-Aex B.h) * (ubase B ξ 0 / ξ.1),
      qC B.h ξ ^ (2 * Aex B.h + 1/2) * qC B.h ξ ^ (-Aex B.h) * dZ (fun η => ubase B η 1) ξ;
     0, 0, qC B.h ξ ^ (2 * Aex B.h + 1/2) * qC B.h ξ ^ (-Aex B.h) * dZ (fun η => ubase B η 2) ξ]

